دالة ضرب_مصفوفتين(مصفوفة_أ، مصفوفة_ب) {
    متغير ن = طول(مصفوفة_أ)
    متغير مصفوفة_ج = []
    من_أجل (أ من ٠ إلى ن - ١) {
        متغير سطر = []
        من_أجل (ب من ٠ إلى ن - ١) {
            متغير مجموع = ٠
            من_أجل (ج من ٠ إلى ن - ١) {
                مجموع = مجموع + مصفوفة_أ[أ][ج] * مصفوفة_ب[ج][ب]
            }
            سطر = أضف(سطر، مجموع)
        }
        مصفوفة_ج = أضف(مصفوفة_ج، سطر)
    }
    ارجع مصفوفة_ج
}
